// Pure-JavaScript HMAC implementation (RFC 2104), parameterized by hash function.
import { sha1, SHA1_BLOCK_SIZE, SHA1_DIGEST_SIZE } from './sha1.mjs';

// A small hash "module" descriptor, mirroring how Python's hmac takes a digestmodule.
export const sha1Module = {
  blockSize: SHA1_BLOCK_SIZE,
  digestSize: SHA1_DIGEST_SIZE,
  digest: sha1,
};

export function hmac(keyBytes, messageBytes, hashModule) {
  const blockSize = hashModule.blockSize;
  let key = keyBytes.slice();

  // Keys longer than the block size are hashed first
  if (key.length > blockSize) {
    key = hashModule.digest(key);
  }
  // Pad key to block size with zeros
  while (key.length < blockSize) {
    key.push(0);
  }

  const oKeyPad = key.map((b) => b ^ 0x5c);
  const iKeyPad = key.map((b) => b ^ 0x36);

  return hashModule.digest(oKeyPad.concat(hashModule.digest(iKeyPad.concat(messageBytes))));
}

export function hmacSha1(keyBytes, messageBytes) {
  return hmac(keyBytes, messageBytes, sha1Module);
}

