// Pure-JavaScript PBKDF2 key derivation (RFC 2898),
// matching the Python `pbkdf2` package defaults:
//   iterations = 1000, PRF = HMAC-SHA1.
import { hmac, sha1Module } from './hmac.mjs';

// Derive `dkLen` bytes from passphrase/salt using PBKDF2.
// All inputs/outputs are arrays of byte values (0-255).
export function pbkdf2(passphraseBytes, saltBytes, iterations, dkLen, hashModule) {
  const hLen = hashModule.digestSize;
  const blockCount = Math.ceil(dkLen / hLen);
  const derived = [];

  for (let blockIndex = 1; blockIndex <= blockCount; blockIndex++) {
    // U_1 = PRF(password, salt || INT_32_BE(blockIndex))
    const saltBlock = saltBytes.concat([
      (blockIndex >>> 24) & 0xff,
      (blockIndex >>> 16) & 0xff,
      (blockIndex >>> 8) & 0xff,
      blockIndex & 0xff,
    ]);
    let u = hmac(passphraseBytes, saltBlock, hashModule);
    let t = u.slice();

    for (let i = 2; i <= iterations; i++) {
      u = hmac(passphraseBytes, u, hashModule);
      for (let j = 0; j < hLen; j++) {
        t[j] ^= u[j];
      }
    }

    for (const b of t) {
      derived.push(b);
    }
  }

  return derived.slice(0, dkLen);
}

// Convenience wrapper matching the Python usage pbkdf2.PBKDF2(a, salt).read(24)
export function pbkdf2Sha1(passphraseBytes, saltBytes, dkLen) {
  return pbkdf2(passphraseBytes, saltBytes, 1000, dkLen, sha1Module);
}

