// Minimal command-line parser replicating Python argparse behavior
// for this script: three required string options --a, --b, --c.

const PROGRAM_NAME = 'test7.mjs';

function usage() {
  return `usage: ${PROGRAM_NAME} [-h] --a A --b B --c C`;
}

function fail(message) {
  process.stderr.write(usage() + '\n');
  process.stderr.write(`${PROGRAM_NAME}: error: ${message}\n`);
  process.exit(2);
}

export function parseArgs(argv) {
  const specs = { '--a': 'a', '--b': 'b', '--c': 'c' };
  const result = { a: undefined, b: undefined, c: undefined };

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      process.stdout.write(usage() + '\n');
      process.exit(0);
    }

    let name = token;
    let inlineValue;
    const eq = token.indexOf('=');
    if (token.startsWith('--') && eq !== -1) {
      name = token.slice(0, eq);
      inlineValue = token.slice(eq + 1);
    }

    if (Object.prototype.hasOwnProperty.call(specs, name)) {
      let value;
      if (inlineValue !== undefined) {
        value = inlineValue;
      } else {
        if (i + 1 >= argv.length) {
          fail(`argument ${name}: expected one argument`);
        }
        value = argv[++i];
      }
      result[specs[name]] = value;
    } else {
      fail(`unrecognized arguments: ${token}`);
    }
  }

  const missing = [];
  for (const [flag, key] of Object.entries(specs)) {
    if (result[key] === undefined) {
      missing.push(flag);
    }
  }
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }

  return result;
}

