// Entry file — mirrors /workspace/dataset/pbkdf2/test7.py
// PBKDF2 with the same passphrase but two different salts.
import { parseArgs } from './cli.mjs';
import { pbkdf2Sha1 } from './pbkdf2.mjs';

function utf8Bytes(str) {
  return Array.from(Buffer.from(str, 'utf8'));
}

function toHex(bytes) {
  return Buffer.from(bytes).toString('hex');
}

const args = parseArgs(process.argv.slice(2));

const key1 = pbkdf2Sha1(utf8Bytes(args.a), utf8Bytes(args.b), 24);
console.log(toHex(key1));

const key2 = pbkdf2Sha1(utf8Bytes(args.a), utf8Bytes(args.c), 24);
console.log(toHex(key2));

